import math

def find_zero(xs: list) -> float:
    """
    xs are coefficients of a polynomial.
    find_zero find x such that poly(x) = 0.
    find_zero returns only one zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> round(find_zero([1, 2]), 2) # f(x) = 1 + 2x
    -0.5
    >>> round(find_zero([-6, 11, -6, 1]), 2) # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
    """
    if len(xs) % 2 == 0 and len(xs) > 0:
        pass
    else:
        raise ValueError("The length of xs must be even and greater than 0.")

    if all(coeff == 0 for coeff in xs[:-1]):
        raise ValueError("The polynomial must not be constant.")

    def poly(coefficients, x):
        return sum([coeff * math.pow(x, i) for i, coeff in enumerate(coefficients)])

    def derivative(coefficients, x):
        return sum([i * coeff * math.pow(x, i - 1) for i, coeff in enumerate(coefficients) if i > 0])

    x = max(abs(coeff) for coeff in xs)  # Initial guess based on the largest non-zero coefficient
    tolerance = 1e-6
    max_iterations = 1000

    for _ in range(max_iterations):
        fx = poly(xs, x)
        fpx = derivative(xs, x)
        if abs(fpx) < tolerance:
            return round(x)
        x -= fx / fpx

    return None  # Convergence failure
```

